, "skill": {"id": "service.quota_suspension_enforcement", "version": 1, "type": "decision", "trigger": {"keywords": ["quota", "suspended", "start_instance", "capacity", "policy", "QUOTA_EXCEEDED", "PROJECT_SUSPENDED"]}, "preconditions": ["The fixed customer identity has applicable scope permission for the requested project.", "Every write is among the exact current Customer-approved operations.", "Project status and resource quota information are available via read tools."], "procedure": ["Query the target project status and current resource usage with get_project.", "If the project status is suspended, refuse the operation citing PROJECT_SUSPENDED policy and preserve prestate.", "Query the target instance specifications with get_instance to determine CPU, memory requirements.", "Calculate whether starting the instance would exceed project quota for CPU, memory, or instance count.", "If any resource would exceed quota, refuse the operation citing QUOTA_EXCEEDED policy and preserve prestate.", "If project is active and quota permits, proceed with the requested start_instance operation."], "postconditions": ["If the operation succeeds, report the instance running state and updated project resource usage.", "If refused due to PROJECT_SUSPENDED, preserve prestate and explain the suspension policy.", "If refused due to QUOTA_EXCEEDED, preserve prestate and explain which resource exceeds quota."], "recovery": ["If a tool fails, report that failure and inspect permitted state before choosing a next step.", "When a policy prerequisite cannot be met, explain the specific policy code and reason instead of refusing all requests."]}}

